def _handle_vulnerabilities_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    try:
        # Validate fully before touching any state, so a bad payload can
        # never leave a partial alert even for a missing resource.
        advisory_id, component, severity, summary, fix_version = (
            build_vulnerability_fields(payload)
        )
    except VulnerabilityValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        entry = vulnerability_store.add(raw_id, payload)
    except VulnerabilityDuplicateError as exc:
        return _error(
            start_response,
            "409 Conflict",
            exc.code,
            exc.message,
        )

    return _json_response(
        start_response,
        "201 Created",
        entry.to_dict(),
        trailing_newline=True,
    )


