def test_path_id_rules(self) -> None:
    for path in (
        "/resources//vulnerabilities",
        "/resources/a%2Fb/vulnerabilities",
    ):
        status, _headers, body = call(
            "POST",
            path,
            alert(),
        )
        # The encoded slash is decoded by real servers; PATH_INFO here
        # is used verbatim, so only the genuinely empty id is asserted.
        if path == "/resources//vulnerabilities":
            self.assertEqual(status, "400 Bad Request")
            self.assertEqual(body["error"], "invalid_request")

